script:
card({ name: "Flick ball", icon: 'sports' });
const words = {
  hint: "Drag the ball and flick it",
};

function init() {
  return { x: 0.5, y: 0.5, vx: 0, vy: 0, t: 0 };
}

on.flick = (s, a, ctx) => {
  s.x = a.x;
  s.y = a.y;
  s.vx = (a.dx || 0) * 3;
  s.vy = (a.dy || 0) * 3;
  s.t = ctx.time;
};

// Where an axis is now: start + distance (speed falling off), folded into the
// walls so it bounces instead of leaving the box.
function roll(p0, v, dt) {
  const m = 0.08;
  const span = 1 - 2 * m;
  const decay = 1.8;
  const d = v * (1 - Math.exp(-decay * dt)) / decay;
  let u = Math.abs((p0 - m + d) / span) % 2;
  return m + (u > 1 ? 2 - u : u) * span;
}

function view(state, me, now) {
  const dt = Math.min((now - state.t) / 1000, 6);
  if (dt < 4) every(30);
  return column([
    text(words.hint, { size: 'small', tone: 'muted', align: 'center' }),
    canvas({
      ratio: 1,
      onDrag: 'flick',
      shapes: [circle(roll(state.x, state.vx, dt), roll(state.y, state.vy, dt), 0.08, { fill: 'accent' })],
    }),
  ]);
}
